In `name_length`:
```c
while (*encoded)
{
    top = (*encoded & INDIR_MASK);
    if (top == INDIR_MASK)
    {
        offset = (*encoded & ~INDIR_MASK) << 8 | *(encoded + 1);
        if (offset >= alen)
            return -1;
        encoded = abuf + offset;
        ++indir;
