    else if (top == 0x00)
    {
        offset = *encoded;
        if (encoded + offset + 1 >= abuf + alen)
            return -1;
        encoded++;
        while (offset--)
        {
            n += (*encoded == '.' || *encoded == '\\') ? 2 : 1;
            encoded++;
        }
        n++;
    }
    else
    {
        return -1;
    }
}
return (n) ? n - 1 : n;
```

